PROCEDURE @@proc@@ (p_ids IN SYS.ODCINUMBERLIST) IS
    l_name VARCHAR2(100);
BEGIN
    FOR i IN 1 .. p_ids.COUNT LOOP
        SELECT @@col@@ -- @expect
          INTO l_name
          FROM @@tab@@
         WHERE id = p_ids(i);
        DBMS_OUTPUT.PUT_LINE(l_name);
    END LOOP;
END @@proc@@;

FUNCTION @@proc@@ (p_id IN NUMBER, p_use_alt IN BOOLEAN) RETURN VARCHAR2 IS
    l_val VARCHAR2(100);
BEGIN
    IF p_use_alt THEN
        SELECT @@col2@@ INTO l_val FROM @@tab2@@ WHERE id = p_id; -- @expect
    ELSE
        l_val := 'n/a';
    END IF;
    RETURN l_val;
END @@proc@@;

PROCEDURE @@proc@@ (p_id IN NUMBER, p_label IN VARCHAR2) IS
    l_owner VARCHAR2(100);
BEGIN
    INSERT INTO @@tab@@ (id, label) VALUES (p_id, p_label);
    SELECT @@col@@ INTO l_owner -- @expect
      FROM @@tab2@@
     WHERE id = p_id;
    @@proc2@@(l_owner);
EXCEPTION
    WHEN DUP_VAL_ON_INDEX THEN
        UPDATE @@tab@@ SET label = p_label WHERE id = p_id;
END @@proc@@;

FUNCTION @@proc@@ (p_key IN VARCHAR2) RETURN NUMBER IS
    l_amount NUMBER;
BEGIN
    SELECT o.amount -- @expect
      INTO l_amount
      FROM @@tab@@ o
      JOIN @@tab2@@ c ON c.id = o.@@col@@
     WHERE c.code = p_key;
    RETURN l_amount;
END @@proc@@;

PROCEDURE @@proc@@ (p_id IN NUMBER) IS
    l_a VARCHAR2(100);
    l_b VARCHAR2(100);
BEGIN
    BEGIN
        SELECT @@col@@ INTO l_a FROM @@tab@@ WHERE id = p_id;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            l_a := NULL;
    END;
    SELECT @@col2@@ INTO l_b FROM @@tab2@@ WHERE id = p_id; -- @expect
    @@proc2@@(l_a, l_b);
END @@proc@@;

