PROCEDURE @@proc@@ (p_id IN NUMBER) IS
    l_name VARCHAR2(100);
BEGIN
    DECLARE
        l_inner VARCHAR2(100);
    BEGIN
        SELECT @@col@@
          INTO l_inner
          FROM @@tab@@
         WHERE id = p_id;
        l_name := UPPER(l_inner);
    END;
    @@proc2@@(l_name);
EXCEPTION
    WHEN NO_DATA_FOUND THEN
        @@proc2@@('unknown');
END @@proc@@;

PROCEDURE @@proc@@ (p_dept IN NUMBER, p_total OUT NUMBER, p_avg OUT NUMBER) IS
    l_cnt NUMBER;
BEGIN
    SELECT COUNT(*) INTO l_cnt FROM @@tab@@ WHERE dept_id = p_dept;
    SELECT SUM(@@col@@), AVG(@@col@@)
      INTO p_total, p_avg
      FROM @@tab@@
     WHERE dept_id = p_dept;
    IF l_cnt = 0 THEN
        p_total := 0;
    END IF;
END @@proc@@;

FUNCTION @@proc@@ (p_days IN NUMBER) RETURN DATE IS
    l_now DATE;
BEGIN
    select sysdate
      into l_now
      from dual;
    RETURN l_now + p_days;
END @@proc@@;

FUNCTION @@proc@@ (p_code IN VARCHAR2) RETURN NUMBER IS
    l_id NUMBER;
BEGIN
    SELECT id
      INTO l_id
      FROM @@tab@@
     WHERE code = p_code;
    RETURN l_id;
EXCEPTION
    WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN
        RETURN NULL;
END @@proc@@;

PROCEDURE @@proc@@ (p_run_id IN NUMBER) IS
    l_ids SYS.ODCINUMBERLIST;
BEGIN
    SELECT id
      BULK COLLECT INTO l_ids
      FROM @@tab@@
     WHERE run_id = p_run_id;
    FOR i IN 1 .. l_ids.COUNT LOOP
        @@proc2@@(l_ids(i));
    END LOOP;
END @@proc@@;
